// Generates TypeScript types and Java records from protocol/schemas.
// Run it with "pnpm protocol:gen"; "pnpm protocol:check" fails when the generated code is stale.
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { compile, type JSONSchema } from "json-schema-to-typescript";

const PROTOCOL_DIR = join(import.meta.dirname, "..");
const SCHEMAS_DIR = join(PROTOCOL_DIR, "schemas");
const TS_DIR = join(PROTOCOL_DIR, "generated");
const NOTICE =
  "Generated by pnpm protocol:gen from protocol/schemas. Do not edit.";
/** Schemas that are not messages: the shared types and the envelope. */
const NOT_MESSAGES = new Set(["common.schema.json", "envelope.schema.json"]);

export type Direction = "client" | "server";

export interface Schema {
  title?: string;
  "x-message"?: { type: string; direction: Direction };
  [keyword: string]: unknown;
}

export interface Message {
  type: string;
  direction: Direction;
  file: string;
  schema: Schema;
}

export interface Version {
  current: number;
  min_supported: number;
}

function readJson<T>(path: string): T {
  return JSON.parse(readFileSync(path, "utf8")) as T;
}

/** Reads version.json and checks that 1 <= min_supported <= current. */
export function readVersion(): Version {
  const version = readJson<Version>(join(PROTOCOL_DIR, "version.json"));
  if (
    !Number.isInteger(version.current) ||
    !Number.isInteger(version.min_supported)
  ) {
    throw new Error("version.json: current and min_supported must be integers");
  }
  if (version.min_supported < 1 || version.min_supported > version.current) {
    throw new Error("version.json: expected 1 <= min_supported <= current");
  }
  return version;
}

/** Checks the x-message block of one schema file and turns it into a Message. */
export function toMessage(file: string, schema: Schema): Message {
  const meta = schema["x-message"];
  if (!meta) {
    throw new Error(`${file}: missing "x-message"`);
  }
  if (!/^[a-z][a-z0-9]*(_[a-z0-9]+)*$/.test(meta.type)) {
    throw new Error(`${file}: type "${meta.type}" is not snake_case`);
  }
  if (file !== `${meta.type}.schema.json`) {
    throw new Error(`${file}: expected the file name ${meta.type}.schema.json`);
  }
  if (meta.direction !== "client" && meta.direction !== "server") {
    throw new Error(`${file}: direction must be "client" or "server"`);
  }
  if (!schema.title || !/^[A-Z][A-Za-z0-9]*$/.test(schema.title)) {
    throw new Error(`${file}: title must be PascalCase`);
  }
  return { type: meta.type, direction: meta.direction, file, schema };
}

/** Every message schema, sorted by file name so that the output is always the same. */
export function readMessages(): Message[] {
  return readdirSync(SCHEMAS_DIR)
    .filter((file) => file.endsWith(".schema.json") && !NOT_MESSAGES.has(file))
    .sort()
    .map((file) => toMessage(file, readJson<Schema>(join(SCHEMAS_DIR, file))));
}

export function byDirection(
  messages: Message[],
  direction: Direction,
): Message[] {
  return messages.filter((message) => message.direction === direction);
}

/** The name of a message's payload type: Hello becomes HelloPayload. */
export function payloadName(message: Message): string {
  return `${message.schema.title}Payload`;
}

/** An object schema whose properties are the payloads of one direction, keyed by type. */
function directionSchema(
  messages: Message[],
  direction: Direction,
  title: string,
): JSONSchema {
  const own = byDirection(messages, direction);
  const properties: Record<string, JSONSchema> = {};
  for (const message of own) {
    const { "x-message": _meta, ...payload } = message.schema;
    properties[message.type] = { ...payload, title: payloadName(message) };
  }
  return {
    title,
    description: `Messages the ${direction} sends: type -> payload.`,
    type: "object",
    properties,
    required: own.map((message) => message.type),
    additionalProperties: false,
  };
}

/** The parts no payload schema can express: version, envelope, unions and frame. */
function typescriptTail(version: Version): string {
  return `
/** Protocol version this code speaks. */
export const PROTOCOL_VERSION = ${version.current};

/** Oldest protocol version the server still accepts. */
export const MIN_SUPPORTED_PROTOCOL_VERSION = ${version.min_supported};

/** The envelope shared by every message. */
export interface Envelope<T extends string, P> {
  type: T;
  seq: number;
  payload: P;
}

type EnvelopeOf<M> = {
  [T in keyof M & string]: Envelope<T, M[T]>;
}[keyof M & string];

/** Any message the client sends, discriminated by type. */
export type ClientMessage = EnvelopeOf<ClientMessages>;

/** Any message the server sends, discriminated by type. */
export type ServerMessage = EnvelopeOf<ServerMessages>;

/** One WebSocket frame from the server: the events of one tick, in order. */
export type ServerFrame = ServerMessage[];
`;
}

/** The text of generated/index.ts. */
export async function typescriptFile(
  version: Version,
  messages: Message[],
): Promise<string> {
  const root: JSONSchema = {
    title: "Protocol",
    description: "Every message of the protocol, by direction.",
    type: "object",
    properties: {
      client: directionSchema(messages, "client", "ClientMessages"),
      server: directionSchema(messages, "server", "ServerMessages"),
    },
    required: ["client", "server"],
    additionalProperties: false,
  };
  const types = await compile(root, "Protocol", {
    cwd: SCHEMAS_DIR,
    bannerComment: `// ${NOTICE}`,
    additionalProperties: false,
  });
  return types + typescriptTail(version);
}

async function main(): Promise<void> {
  try {
    const version = readVersion();
    const messages = readMessages();
    console.log(
      `Protocol version ${version.current} (min supported ${version.min_supported})`,
    );
    for (const direction of ["client", "server"] as const) {
      const types = byDirection(messages, direction).map(
        (message) => message.type,
      );
      console.log(`${direction}: ${types.join(", ")}`);
    }
    mkdirSync(TS_DIR, { recursive: true });
    writeFileSync(
      join(TS_DIR, "index.ts"),
      await typescriptFile(version, messages),
    );
  } catch (error) {
    console.error(error instanceof Error ? error.message : error);
    process.exitCode = 1;
  }
}

// Runs only when the file is executed, not when a test imports it.
if (import.meta.main) {
  await main();
}
